// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(!c.blacklist(actor));
        vm.assume(!c.distributionFinished());

        uint256 valueBefore = c.value();
        uint256 remainingBefore = c.totalRemaining();
        uint256 balanceBefore = c.balanceOf(actor);
        uint256 expectedCredit = valueBefore <= remainingBefore ? valueBefore : remainingBefore;

        vm.prank(actor);
        c.getTokens();

        // Rule: getTokens credits the caller with exactly min(value, totalRemaining) tokens.
        assertTrue(c.balanceOf(actor) == balanceBefore + expectedCredit);
    }
}
